// Evidence-based findings for the Inflation page.
//
// Every finding is a sentence assembled from numbers the page displays: it names
// the period, the unit and the comparison, and states a FACT about the data. It
// never says why something happened — the data on this page cannot establish
// causes, and a finding that implied one would be an invention. Findings are
// generated by deterministic templates, not by a model, so the same data always
// yields the same text and every number in it can be found in a chart or table.
//
// findings.test.ts scans every sentence for causal language as a guard.

import { acceleration, alignedLatest, latestCommonYear, policyRateAt, rankDescending, type AnnualPoint } from "@/lib/inflation/analytics";
import { groupLabel } from "@/lib/inflation/groups";
import { monthLabel, shiftMonth, toMonthMap, type MonthKey } from "@/lib/inflation/periods";
import type { InflationViewModel } from "@/lib/inflation/viewModel";
import { formatPercent, formatPp, formatValue } from "@/lib/analytics/scales";

export interface Finding {
  id: string;
  /** The sentence shown to the reader. */
  text: string;
  /** The period(s) it is about, for the reader to check against the charts. */
  period: string;
  /** Which series it was computed from. */
  basis: string;
}

const COUNTRY_NAME: Record<string, string> = { PAK: "Pakistan", IND: "India", BGD: "Bangladesh", LKA: "Sri Lanka" };

function moved(delta: number): string {
  if (Math.abs(delta) < 0.05) return "unchanged";
  return delta > 0 ? "up" : "down";
}

export function buildFindings(vm: InflationViewModel): Finding[] {
  const out: Finding[] = [];
  const hm = toMonthMap(vm.headline);

  // 1 & 2. Headline: latest, previous month, a year earlier.
  if (vm.horizon) {
    const latest = hm.get(vm.horizon) as number;
    const prevKey = shiftMonth(vm.horizon, -1);
    const prev = hm.get(prevKey);
    if (prev !== undefined) {
      const d = latest - prev;
      out.push({
        id: "headline-month",
        text: `Headline CPI inflation was ${formatPercent(latest)} in ${monthLabel(vm.horizon)}, ${moved(d) === "unchanged" ? "unchanged from" : `${moved(d)} ${formatValue(Math.abs(d))} percentage points from`} ${formatPercent(prev)} in ${monthLabel(prevKey)}.`,
        period: `${monthLabel(prevKey)} – ${monthLabel(vm.horizon)}`,
        basis: "National CPI, year-on-year, published",
      });
    }
    const yearKey = shiftMonth(vm.horizon, -12);
    const yearAgo = hm.get(yearKey);
    if (yearAgo !== undefined) {
      const d = latest - yearAgo;
      out.push({
        id: "headline-year",
        text: `Twelve months earlier, in ${monthLabel(yearKey)}, headline inflation was ${formatPercent(yearAgo)}; the rate is ${moved(d) === "unchanged" ? "unchanged" : `${moved(d)} ${formatValue(Math.abs(d))} percentage points`} over the year.`,
        period: `${monthLabel(yearKey)} – ${monthLabel(vm.horizon)}`,
        basis: "National CPI, year-on-year, published",
      });
    }

    // 3. Extremes of the published series.
    if (vm.headline.length > 12) {
      const hi = rankDescending(vm.headline, (p) => p.value)[0];
      const lo = rankDescending(vm.headline, (p) => -p.value)[0];
      out.push({
        id: "headline-extremes",
        text: `Across the ${vm.headline.length} months from ${monthLabel(vm.headline[0].month)} to ${monthLabel(vm.headline[vm.headline.length - 1].month)}, the highest headline reading was ${formatPercent(hi.value)} (${monthLabel(hi.month)}) and the lowest ${formatPercent(lo.value)} (${monthLabel(lo.month)}).`,
        period: `${monthLabel(vm.headline[0].month)} – ${monthLabel(vm.headline[vm.headline.length - 1].month)}`,
        basis: "National CPI, year-on-year, published",
      });
    }

    // 4. Direction of the last six month-to-month changes.
    const acc = acceleration(vm.headline).slice(-6);
    if (acc.length === 6) {
      const rises = acc.filter((p) => p.value > 0).length;
      out.push({
        id: "headline-direction",
        text: `Over the six months to ${monthLabel(vm.horizon)}, the headline rate rose in ${rises} month-to-month readings and fell in ${6 - rises}.`,
        period: `${monthLabel(acc[0].month)} – ${monthLabel(vm.horizon)}`,
        basis: "National CPI, year-on-year, published",
      });
    }
  }

  // 5. The three measures at the last month they share.
  const aligned = alignedLatest({ headline: vm.headline, core: vm.core, food: vm.food });
  if (aligned) {
    const { headline, core, food } = aligned.latest;
    out.push({
      id: "measures",
      text: `In ${monthLabel(aligned.latestMonth)}, headline CPI (national) was ${formatPercent(headline)}, core inflation (urban non-food non-energy) ${formatPercent(core)} and food inflation (urban) ${formatPercent(food)}. These cover different groups of households, so the gaps between them are not like-for-like.`,
      period: monthLabel(aligned.latestMonth),
      basis: "National CPI; Urban NFNE core; Urban Food CPI — all year-on-year, published",
    });
  }

  // 6–8. Expenditure groups.
  const g = vm.groups;
  if (g) {
    const month = g.latestMonth;
    const rows = Object.keys(g.yoy)
      .map(Number)
      .map((no) => ({ no, yoy: g.yoy[no].find((p) => p.month === month)?.value ?? null }))
      .filter((r): r is { no: number; yoy: number } => r.yoy !== null);
    if (rows.length > 0) {
      const ranked = rankDescending(rows, (r) => r.yoy);
      const top = ranked[0];
      const bottom = ranked[ranked.length - 1];
      out.push({
        id: "group-extremes",
        text: `In ${monthLabel(month)}, ${groupLabel(top.no).name} had the highest year-on-year inflation of the ${rows.length} CPI groups (${formatPercent(top.yoy)}) and ${groupLabel(bottom.no).name} the lowest (${formatPercent(bottom.yoy)}).`,
        period: monthLabel(month),
        basis: "PBS CPI group indices, year-on-year, derived from the index",
      });
    }
    const latestRow = g.contribYoY.find((r) => r.month === month);
    if (latestRow) {
      const ranked = rankDescending(Object.entries(latestRow.byGroup).map(([no, c]) => ({ no: Number(no), c })), (r) => r.c);
      const [a, b, c3] = ranked;
      out.push({
        id: "group-contributions",
        text: `Of the ${formatValue(latestRow.total, 2)}-percentage-point rise in the CPI over the twelve months to ${monthLabel(month)}, ${groupLabel(a.no).name} contributed ${formatValue(a.c, 2)}, ${groupLabel(b.no).name} ${formatValue(b.c, 2)} and ${groupLabel(c3.no).name} ${formatValue(c3.c, 2)} — together ${formatValue(((a.c + b.c + c3.c) / latestRow.total) * 100, 0)}% of the total.`,
        period: `${monthLabel(latestRow.baseMonth)} – ${monthLabel(month)}`,
        basis: "PBS CPI group indices and fixed basket weights; contribution = weight × change in group index ÷ headline index",
      });
      // Contribution relative to weight for the most volatile mover.
      const byRate = rankDescending(rows, (r) => r.yoy)[0];
      const w = g.weights[byRate.no];
      const contrib = latestRow.byGroup[byRate.no];
      out.push({
        id: "group-weight-vs-contribution",
        text: `${groupLabel(byRate.no).name} has a ${formatValue(w, 1)}% weight in the basket and the highest group inflation (${formatPercent(byRate.yoy)}); its contribution to the headline change was ${formatValue(contrib, 2)} percentage points.`,
        period: monthLabel(month),
        basis: "PBS CPI group indices and fixed basket weights",
      });
    }
  }

  // 9. Policy rate alongside inflation — juxtaposed, not connected.
  if (vm.horizon && vm.policy.length > 0) {
    const rate = policyRateAt(vm.policy, vm.horizon);
    // Only decisions dated in or before the as-of month: a later decision is not "in effect" for it.
    const upTo = vm.policy.filter((d) => d.date.slice(0, 7) <= (vm.horizon as MonthKey));
    const last = upTo[upTo.length - 1];
    const before = upTo.length > 1 ? upTo[upTo.length - 2] : null;
    const latestHeadline = hm.get(vm.horizon);
    if (rate !== null && last && latestHeadline !== undefined) {
      out.push({
        id: "policy",
        text: `The SBP policy rate in effect at the end of ${monthLabel(vm.horizon)} was ${formatPercent(rate, 2)}${before ? ` (last decision ${last.date}, from ${formatPercent(before.value, 2)})` : ""}; headline inflation that month was ${formatPercent(latestHeadline)}. The two are shown together for context; the data here does not measure the effect of one on the other.`,
        period: monthLabel(vm.horizon),
        basis: "SBP policy rate decisions; National CPI year-on-year",
      });
    }
  }

  // 10. International, latest common year.
  if (vm.intl) {
    const year = latestCommonYear(vm.intl.series);
    if (year !== null) {
      const rows = Object.entries(vm.intl.series)
        .map(([code, pts]) => ({ code, v: (pts as AnnualPoint[]).find((p) => p.year === year)?.value ?? null }))
        .filter((r): r is { code: string; v: number } => r.v !== null);
      const ranked = rankDescending(rows, (r) => r.v);
      out.push({
        id: "international",
        text: `In ${year}, consumer-price inflation (annual average, World Bank) was ${ranked.map((r) => `${COUNTRY_NAME[r.code] ?? r.code} ${formatPercent(r.v, 2)}`).join(", ")}.`,
        period: String(year),
        basis: "World Bank FP.CPI.TOTL.ZG, annual %, calendar years",
      });
    }
  }
  return out;
}

export { formatPp };
